mapper.select:
SELECT id, portal_name, portal_code, portal_type, logged_url, status_cd
FROM bt_external_portal
WHERE status_cd != '00X'

  AND (
  portal_name LIKE #{query.keyword}
  OR
  portal_code LIKE #{query.keyword}
  )


  AND portal_type = #{query.portalType}


  AND status_cd = '00A'


  AND status_cd = '00D'


  AND default_tenant_id = #{query.tenantId}

SELECT id, portal_name, portal_code, default_tenant_id, login_url, logged_url, cookie_name, url_param_name
FROM bt_external_portal
WHERE status_cd = '00A'
  AND portal_type = #{portalType}
  AND portal_code = #{portalCode}
